INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r28', 1, 'Zagrej rernu na 180°C.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r28', 2, 'Samelji ovsene u blenderu, dodaj ostale sastojke i izmiksaj.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
