INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r31', 1, 'Skuvaj kinou prema uputstvu.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r31', 2, 'Povrće iseci, prelij polovinom ulja i ispeci 20 minuta na 200°C.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r31', 3, 'Pomešaj kinou, leblebije i povrće, pa začini limunom i ostatkom ulja.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r32', 1, 'Skuvaj integralni pirinač.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r32', 2, 'Proprži luk i ćuretinu dok meso ne promeni boju.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r32', 3, 'Dodaj papriku, pelat, pasulj, čili i kim; kuvaj 25 minuta.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
