INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r33', 1, 'Skuvaj krompir i boraniju dok ne omekšaju.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
