INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r34', 1, 'Skuvaj pirinač posebno.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r34', 2, 'Na ulju proprži luk i šargarepu, dodaj sočivo i pelat.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
