INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r34', 4, 'Posluži uz integralni pirinač.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r35', 1, 'Skuvaj jaje 8-9 minuta i iseci na četvrtine.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r35', 2, 'Pomešaj salatu, paradajz, sardinu i jaje.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
