INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r36', 1, 'Skuvaj heljdine rezance prema uputstvu.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r36', 2, 'Tofu iseci na kockice i proprži na malo susamovog ulja.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
