INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r36', 4, 'Pomešaj sa rezancima i posluži.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r37', 1, 'Iseci krušku na kriške.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
