INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r38', 1, 'Skuvaj edamame 4-5 minuta i posoli blago.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
