INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r39', 1, 'Skuvaj integralnu testeninu al dente.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r39', 2, 'Na maslinovom ulju kratko omekšaj paradajz i spanać.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
