INSERT INTO recipe_steps (recipe_id, step_number, instruction) VALUES ('r40', 2, 'Pomešaj salatu, pasulj, paradajz i avokado.') ON CONFLICT (recipe_id, step_number) DO UPDATE SET instruction = EXCLUDED.instruction;
